function globUsedPlugin() {
    return {
        name: 'glob-used',
        transform: {
            filter: { code: 'import.meta.globUsed' },
            handler(code) {
                return { code: code.replaceAll('import.meta.globUsed', '_bke=import.meta.glob'), map: null }
            }
        },
        renderChunk(code) {
            return { code: code.replaceAll(/_bke\s=\s/g, m => ' '.repeat(m.length)), map: null }
        }
    }
}
```

